import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().execute();
    }

    void execute() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        final int MOD = 998244353;
        int n = in.readInt();
        int k = in.readInt();
        int[] basis = new int[10];
        for (int i = 0; i < k; i++) {
            int x = in.readInt();
            basis[x] = 1;
        }

        int[] resultPoly = new int[]{1};
        int exp = n / 2;

        while (true) {
            if ((exp & 1) == 1) {
                resultPoly = multiplyPolynomials(resultPoly, basis, MOD);
            }
            exp >>= 1;
            if (exp == 0) break;
            basis = multiplyPolynomials(basis, basis, MOD);
        }

        long answer = 0;
        for (int coef : resultPoly) {
            answer = (answer + (long) coef * coef) % MOD;
        }
        out.println(answer);
        out.close();
    }

    int[] multiplyPolynomials(int[] a, int[] b, int mod) {
        int targetSize = a.length + b.length - 1;
        int size = Math.max(2, Integer.highestOneBit(targetSize - 1) << 1);

        double[] ra = new double[size];
        double[] ia = new double[size];
        for (int i = 0; i < a.length; i++) {
            long x = ((long)a[i] % mod + mod) % mod;
            ra[i] = x & 0x7FFF;
            ia[i] = x >> 15;
        }
        performFFT(ra, ia, false);

        double[] rb = new double[size];
        double[] ib = new double[size];
        for (int i = 0; i < b.length; i++) {
            long x = ((long)b[i] % mod + mod) % mod;
            rb[i] = x & 0x7FFF;
            ib[i] = x >> 15;
        }
        performFFT(rb, ib, false);

        double[] resR = new double[size];
        double[] resI = new double[size];
        for (int i = 0; i < size; i++) {
            int j = (size - i) & (size - 1);

            double a1r = (ra[i] + ra[j]) * 0.5;
            double a1i = (ia[i] - ia[j]) * 0.5;
            double a2r = (ia[i] + ia[j]) * 0.5;
            double a2i = (ra[j] - ra[i]) * 0.5;

            double b1r = (rb[i] + rb[j]) * 0.5;
            double b1i = (ib[i] - ib[j]) * 0.5;
            double b2r = (ib[i] + ib[j]) * 0.5;
            double b2i = (rb[j] - rb[i]) * 0.5;

            resR[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resI[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
        }

        performFFT(resR, resI, true);

        int[] result = new int[targetSize];
        for (int i = 0; i < targetSize; i++) {
            long valR = Math.round(resR[i]);
            long valI = Math.round(resI[i]);
            long val = (valR + ((valI % mod) << 15)) % mod;
            result[i] = (int) val;
        }
        return result;
    }

    void performFFT(double[] real, double[] imag, boolean inverse) {
        int n = real.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);

        for (int i = 1; i < n; i++) {
            int rev = Integer.reverse(i << shift);
            if (i < rev) {
                double tmp = real[i];
                real[i] = real[rev];
                real[rev] = tmp;
                tmp = imag[i];
                imag[i] = imag[rev];
                imag[rev] = tmp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            double[] cosTable = new double[half];
            double[] sinTable = new double[half];
            double sign = inverse ? -1 : 1;
            for (int i = 0; i < half; i++) {
                double angle = 2 * Math.PI * i / len * sign;
                cosTable[i] = Math.cos(angle);
                sinTable[i] = Math.sin(angle);
            }

            for (int start = 0; start < n; start += len) {
                for (int k = 0; k < half; k++) {
                    double wr = cosTable[k];
                    double wi = sinTable[k];
                    double uR = real[start + k];
                    double uI = imag[start + k];
                    double vR = real[start + k + half] * wr - imag[start + k + half] * wi;
                    double vI = real[start + k + half] * wi + imag[start + k + half] * wr;

                    real[start + k] = uR + vR;
                    imag[start + k] = uI + vI;
                    real[start + k + half] = uR - vR;
                    imag[start + k + half] = uI - vI;
                }
            }
        }

        if (inverse) {
            for (int i = 0; i < n; i++) {
                real[i] /= n;
                imag[i] /= n;
            }
        }
    }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buffer = new byte[1024];
        private int ptr, len;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int read() {
            if (len == -1) throw new RuntimeException();
            if (ptr >= len) {
                ptr = 0;
                try { len = stream.read(buffer); } catch (IOException e) { throw new RuntimeException(); }
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int readInt() {
            int c = read();
            while (isSpace(c)) c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new NumberFormatException();
                res = res * 10 + c - '0';
                c = read();
            } while (!isSpace(c));
            return res * sgn;
        }

        private boolean isSpace(int c) {
            return c <= ' ' && (c == ' ' || c == '\n' || c == '\r' || c == '\t');
        }
    }
}
